window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"J6a9lGqO4kk","speaker":"Anita Anand","role":"Foreign Minister","country":"Canada","region":"North America","url":"https://www.youtube.com/watch?v=J6a9lGqO4kk","date":"20260926","title":"🇨🇦 Canada - Foreign Minister Addresses United Nations General Debate, 81st Session | #UNGA","seconds":1193,"words":2021,"counts":{"claims":34,"promises":7,"attacks":2},"topics":[{"topic":"UN reform","share":0.1517,"seconds":181},{"topic":"Ukraine-Russia","share":0.124,"seconds":148},{"topic":"Israel-Palestine","share":0.1198,"seconds":143},{"topic":"Iran","share":0.1151,"seconds":137},{"topic":"Arctic security","share":0.1073,"seconds":128},{"topic":"Canada trade","share":0.0612,"seconds":73},{"topic":"Canada defense","share":0.0562,"seconds":67},{"topic":"AI development","share":0.056,"seconds":67},{"topic":"Canada economy","share":0.053,"seconds":63},{"topic":"Canada human rights","share":0.0525,"seconds":63},{"topic":"Global order","share":0.0516,"seconds":62},{"topic":"Ceremony","share":0.0515,"seconds":61}],"timeline":[[1,62,"Ceremony"],[64,125,"Global order"],[127,197,"Ukraine-Russia"],[199,264,"Arctic security"],[266,329,"Canada economy"],[330,403,"Canada trade"],[405,472,"Canada defense"],[474,536,"Arctic security"],[538,616,"Ukraine-Russia"],[618,679,"Iran"],[682,758,"Iran"],[761,828,"AI development"],[829,892,"Canada human rights"],[893,968,"Israel-Palestine"],[969,1037,"Israel-Palestine"],[1039,1103,"UN reform"],[1104,1173,"UN reform"],[1174,1223,"UN reform"]],"stances":{"Ceremony":"Anita Anand introduces herself as the Minister of Foreign Affairs of Canada and shares her personal background from Nova Scotia before noting a shift in the global order.","Global order":"Anita Anand states that the world is facing a new age of disorder and rupture, but Canada aims to achieve greater strategic autonomy in response.","Ukraine-Russia":"Anita Anand states that Canada is working with over 30 allies and partners to bolster Ukraine and defend against further Russian aggression.","Arctic security":"Anita Anand states that Canada and its Arctic allies are cooperating to maintain stability and security in the region.","Canada economy":"Anita Anand states that Canada is focused on building a stronger economy, diversifying trade, and catalyzing investment.","Canada trade":"Anita Anand states that Canada is actively expanding economic and defense partnerships globally, resulting in significant export growth and new financing commitments.","Canada defense":"Anita Anand states that Canada is increasing its defense spending to over 2% of GDP and aims to reach NATO's 5% target by 2035.","Iran":"Anita Anand states that Iran is the principal threat to peace and security in its region and must never acquire a nuclear weapon.","AI development":"Anita Anand states that Canada will remain a trusted voice in the responsible development of artificial intelligence.","Canada human rights":"Anita Anand states that Canada's candidacy for the Human Rights Council reflects its values and that the rule of law guides its actions abroad.","Israel-Palestine":"Anita Anand states that Canada supports the International Criminal Court, remains committed to the UN Charter, and believes lasting peace requires a negotiated two-state solution where both Israel and Palestine have their rights recognized.","UN reform":"Anita Anand states that the UN must not remain static and should be prepared for future changes."},"claims":[{"t":40,"quote":"I was born in Nova Scotia on Canada's East Coast and grew up there, the daughter of immigrants.","topic":"Ceremony","kind":"fact"},{"t":64,"quote":"As Canadian historian Margaret McMillan has observed, we have arrived in a new age of disorder.","topic":"Global order","kind":"fact"},{"t":78,"quote":"Great powers are walking away from global economic cooperation, dismantling economic integration.","topic":"Global order","kind":"fact"},{"t":189,"quote":"Canada is working with over 30 allies and partners to bolster Ukraine and defend against further Russian aggression.","topic":"Ukraine-Russia","kind":"fact"},{"t":199,"quote":"And in regional groupings like the Arctic 7 and the Nordic Baltic 8, Canada and our Arctic allies are cooperating to keep our region stable and secure.","topic":"Arctic security","kind":"fact"},{"t":212,"quote":"To this end, I welcome Secretary Rubio's convening of the Arctic 7 earlier this","topic":"Arctic security","kind":"fact"},{"t":325,"quote":"catalyzing a trillion dollars of investment in Canada","topic":"Canada economy","kind":"number"},{"t":396,"quote":"we secured nearly $500 billion dollar in new financing commitments to investment in Canada.","topic":"Canada trade","kind":"number"},{"t":446,"quote":"allocating over $80 billion in last year's federal budget","topic":"Canada defense","kind":"number"},{"t":451,"quote":"We are now spending over 2% of our GDP on defense","topic":"Canada defense","kind":"number"},{"t":456,"quote":"building toward NATO's 5% pledge by 2035","topic":"Canada defense","kind":"number"},{"t":474,"quote":"Canada is an Arctic nation and the Arctic is central to our identity, our security and our future.","topic":"Arctic security","kind":"fact"},{"t":508,"quote":"As we mark the 30th anniversary of the Arctic Council, we continue to strive for a region of","topic":"Arctic security","kind":"fact"},{"t":518,"quote":"And to this end, Canada has opened a new consulate in Nuke, Greenland.","topic":"Arctic security","kind":"fact"},{"t":538,"quote":"This agreement is yet another reminder that North America and Europe are stronger together, and as a founding member of NATO, our commitment to the Transatlantic Alliance is ironclad.","topic":"Ukraine-Russia","kind":"fact"},{"t":575,"quote":"Canada is dedicated to advancing the unconditional return of Ukrainian children, unlawfully detained civilians, and prisoners of war.","topic":"Ukraine-Russia","kind":"fact"},{"t":654,"quote":"Canada's position on Iran is Iran is the principal threat to peace and security in its region.","topic":"Iran","kind":"fact"},{"t":665,"quote":"Its threats to navigation rights in the Strait of Hormuz are direct affront to international law.","topic":"Iran","kind":"fact"},{"t":682,"quote":"And Canada is deploying every available tool, including targeted sanctions that I announced this week to confront the Iranian regime's abhorrent behavior.","topic":"Iran","kind":"fact"},{"t":694,"quote":"Here at the United Nations, Canada will again lead the resolution in this very room in the General Assembly on human rights in Iran because we stand firmly with the Iranian people against repression and for human rights, dignity, and aspirations for a better Nearer home, the people of Haiti deserve and the opportunity to build a better We commend the many countries who proposed their assistance to the gang suppression force, in particular the United States.","topic":"Iran","kind":"fact"},{"t":761,"quote":"Throughout the world, Canada will remain a voice that can be trusted to defend maritime security, international law, and the responsible development of artificial intelligence.","topic":"AI development","kind":"fact"},{"t":793,"quote":"We were tragically reminded of the scourge of anti-semitism again when a gunman carried out an attack on a synagogue in Belleville, Ontario, on the holiest day of the Jewish calendar.","topic":"AI development","kind":"fact"},{"t":829,"quote":"Our success is underpinned by this civility, by our democratic institutions and by respect for our differences.","topic":"Canada human rights","kind":"fact"},{"t":843,"quote":"As Prime Minister Carney recently observed, we are a steady partner when predictability is at a premium.","topic":"Canada human rights","kind":"fact"},{"t":854,"quote":"Canada's candidacy for the Human Rights Council for 2028 to 2030 bears witness to our values and to the nations represented here.","topic":"Canada human rights","kind":"fact"},{"t":893,"quote":"This includes our support for those institutions that defend these such as the International Criminal Court.","topic":"Israel-Palestine","kind":"fact"},{"t":904,"quote":"remains unequivocally committed to the charter of the United Nations which Canada helped to shape.","topic":"Israel-Palestine","kind":"fact"},{"t":969,"quote":"The two-state solution remains the guiding principle of our Middle East policy","topic":"Israel-Palestine","kind":"fact"},{"t":998,"quote":"Hamas must play no role in the governance of Israel's settlements in the West Bank are illegal under international law","topic":"Israel-Palestine","kind":"fact"},{"t":1012,"quote":"That is why Canada announced earlier this month that we intend to restrict trade in goods with illegal Israeli settlements","topic":"Israel-Palestine","kind":"fact"},{"t":1039,"quote":"We recently announced financing to the tune of $120 million to help the affected people from Lebanon to Haiti to Gaza","topic":"UN reform","kind":"number"},{"t":1104,"quote":"We would like to thank Mr. Antonio Gutesh for his efforts over the past decade.","topic":"UN reform","kind":"fact"},{"t":1174,"quote":"Though some are turning away from the principles of the United Nations, we remain committed to them.","topic":"UN reform","kind":"fact"},{"t":1182,"quote":"And though some would rather ignore the rupture that we see before our very eyes, we are willing to see the world as it is.","topic":"UN reform","kind":"fact"}],"promises":[{"t":276,"quote":"We will diversify our ties. We will work with trusted partners to strengthen our strategic capabilities, especially in emerging technologies, critical minerals, defense production, and clean and conventional energy.","topic":"Canada economy","kind":"promise"},{"t":294,"quote":"And we will lead other middle powers to act collectively and decisively because middle powers are playing a key role in building the framework for the new international order which is being established as we speak.","topic":"Canada economy","kind":"promise"},{"t":586,"quote":"Next week, I will with Norway and Ukraine a conference on this urgent issue in Toronto.","topic":"Ukraine-Russia","kind":"promise"},{"t":761,"quote":"Throughout the world, Canada will remain a voice that can be trusted to defend maritime security, international law, and the responsible development of artificial intelligence.","topic":"AI development","kind":"promise"},{"t":779,"quote":"We will continue to speak out against the unacceptable rise in hatred, including anti-semitism and Islamophobia, which are plagues that our countries must fight together.","topic":"AI development","kind":"promise"},{"t":982,"quote":"Alongside our partners, we will continue to target those who lead, arm, and finance Hamas and other terrorist organizations","topic":"Israel-Palestine","kind":"promise"},{"t":1203,"quote":"This is the path that Canada will take and we invite you to join us in Thank you. Merci Miglanch.","topic":"UN reform","kind":"promise"}],"attacks":[{"t":611,"quote":"disrupting and deterring the illegal activities of Russia's shadow fleet.","topic":"Ukraine-Russia","target":"Russia"},{"t":672,"quote":"We join our Gulf and European partners in strongly condemning Iran's attacks in the region.","topic":"Iran","target":"Iran"}],"greece":[],"said":[],"pickup":[],"transcript":[{"t":1,"topic":"Ceremony","text":"I now give the floor to her excellency Anita Anon, Minister of Foreign Affairs of Canada. Mr. President, colleagues, and friends. I was born in Nova Scotia on Canada's East Coast and grew up there, the daughter of immigrants. Nova Scotians all know the same thing. The tide does not wait. You must move with it. The tide has turned in the global order as well."},{"t":64,"topic":"Global order","text":"As Canadian historian Margaret McMillan has observed, we have arrived in a new age of disorder. We are facing a rupture, not a Great powers are walking away from global economic cooperation, dismantling economic integration. Great powers want the rest of us to accept what we are offered. And too often, state sovereignty, the cornerstone of the UN charter, has been treated with disdain. We are facing serious challenges in the global order. But at their core, Canadians and billions of others around the world want to live peaceful, prosperous, and predictable lives. That is why in the face of this rupture, Canada's goal is to achieve greater strategic autonomy."},{"t":127,"topic":"Ukraine-Russia","text":"Greater autonomy to make our own choices and to determine our own sovereign We can no longer afford to be overly reliant on any one partner. Instead, we are diversifying our ties and building stronger relationships with new and old partners alike so that our people can enjoy peace and prosperity. We will prioritize decisive, effective action by forging issuebased coalitions of nations that share a sense of urgency on common challenges. We believe that these coalitions are the most flexible, effective, and immediate way to address emerging global challenges. We are already forming these coalitions with small states, middle powers, and great powers alike. Through the coalition of the willing, Canada is working with over 30 allies and partners to bolster Ukraine and defend against further Russian aggression."},{"t":199,"topic":"Arctic security","text":"And in regional groupings like the Arctic 7 and the Nordic Baltic 8, Canada and our Arctic allies are cooperating to keep our region stable and secure. To this end, I welcome Secretary Rubio's convening of the Arctic 7 earlier this At a time when we are forming new we should also strengthen the multilateral system. This is why Canada and our partners throughout the entire have started a new initiative entitled partners for multilateralism. This initiative seeks to support United Nations reform and reform of other institutions to make them more representative, more effective, and more A policy of values-based realism."},{"t":266,"topic":"Canada economy","text":"Understanding the world as it is, we will make the right choices for Canadians while being guided by our values. We will diversify our ties. We will work with trusted partners to strengthen our strategic capabilities, especially in emerging technologies, critical minerals, defense production, and clean and conventional energy. And we will lead other middle powers to act collectively and decisively because middle powers are playing a key role in building the framework for the new international order which is being established as we speak. In the economic realm, Canada is focused on what we can control. building a stronger economy, diversifying our trade, and catalyzing a trillion dollars of investment in Canada."},{"t":330,"topic":"Canada trade","text":"Over the next 5 years, we are exploring new opportunities with partners in the Indo-Pacific, the Gulf region, and Latin America. This includes building renewed partnerships with large economies like India and China. We are strengthening ties between Canada and Europe. Alongside the European Union, we are building an alliance for the future. Thanks to our strategy for Africa, we are boosting our trade links with our African partners. We are making concrete progress. Canadian exports to markets outside of North America have significantly &gt;&gt; Last year, Canada has secured more than 20 new economic and defense partnerships. And at the first ever Canada Investment Summit earlier this month, we secured nearly $500 billion dollar in new financing commitments to investment in Canada."},{"t":405,"topic":"Canada defense","text":"As an energy superpower, we are providing energy supplies to many of our partners around the world while supporting the transition to a more environmentally sustainable future. Because in a rapidly changing world, Canada is a reliable partner and we are ready to work together. We are also ready to work together on enhancing international security. Canada's stepping up and taking greater responsibility for our own defense. We are making the largest defense investments in generations, allocating over $80 billion in last year's federal budget. We are now spending over 2% of our GDP on defense and we are building toward NATO's 5% pledge by 2035. These investments are strengthening our ability to protect Canada and to contribute to peace and security around the world."},{"t":474,"topic":"Arctic security","text":"Canada is an Arctic nation and the Arctic is central to our identity, our security and our future. The Arctic is a region of growing competition and for many Canadians it is simply home. &gt;&gt; This is why we are investing in Arctic in consultation with indigenous peoples. Their participation is a key element of our commitment to As we mark the 30th anniversary of the Arctic Council, we continue to strive for a region of And to this end, Canada has opened a new consulate in Nuke, Greenland. And we are strengthening our ties with our Arctic Canada welcomes the recent agreement between Greenland, Denmark, and the United States to strengthen security in Greenland and the High North."},{"t":538,"topic":"Ukraine-Russia","text":"This agreement is yet another reminder that North America and Europe are stronger together, and as a founding member of NATO, our commitment to the Transatlantic Alliance is ironclad. Alongside our NATO allies, Canada remains resolute in our support for Ukraine. We share Ukraine's commitment to restoring a comprehensive, just, and lasting peace, one based on respect for Ukraine's sovereignty and territorial Canada is dedicated to advancing the unconditional return of Ukrainian children, unlawfully detained civilians, and prisoners of war. Next week, I will with Norway and Ukraine a conference on this urgent issue in Toronto. and Canada with Ukraine will continue to work together to support safe and secure navigation in the Black Sea by strengthening Ukraine's port infrastructure and disrupting and deterring the illegal activities of Russia's shadow fleet."},{"t":618,"topic":"Iran","text":"Canada is also a Pacific nation and we are absolutely committed to a free, open and inclusive Indo-Pacific region. We have increased our naval presence in the Indo-Pacific and are offering the dark vessel detection program to our partners. We will continue to implement UN Security Council sanctions against North Korea and by working with our regional partners, we are cracking down on transnational crime, including scam Canada's position on Iran is Iran is the principal threat to peace and security in its region. It must never acquire a nuclear weapon. Its threats to navigation rights in the Strait of Hormuz are direct affront to international law. We join our Gulf and European partners in strongly condemning Iran's attacks in the region."},{"t":682,"topic":"Iran","text":"And Canada is deploying every available tool, including targeted sanctions that I announced this week to confront the Iranian regime's abhorrent behavior. Here at the United Nations, Canada will again lead the resolution in this very room in the General Assembly on human rights in Iran because we stand firmly with the Iranian people against repression and for human rights, dignity, and aspirations for a better Nearer home, the people of Haiti deserve and the opportunity to build a better We commend the many countries who proposed their assistance to the gang suppression force, in particular the United States. Even if the population in Haiti is still facing significant challenges, we're encouraged by the measures taken by the government of Haiti to prepare for the elections, a sign of progress and hope."},{"t":761,"topic":"AI development","text":"Throughout the world, Canada will remain a voice that can be trusted to defend maritime security, international law, and the responsible development of artificial intelligence. We will continue to speak out against the unacceptable rise in hatred, including anti-semitism and Islamophobia, which are plagues that our countries must fight together. We were tragically reminded of the scourge of anti-semitism again when a gunman carried out an attack on a synagogue in Belleville, Ontario, on the holiest day of the Jewish calendar. As Canada navigates this global rupture, our response is grounded in our highest Canada is an open, pluralistic society with a public square full of robust and civil debate."},{"t":829,"topic":"Canada human rights","text":"Our success is underpinned by this civility, by our democratic institutions and by respect for our differences. As Prime Minister Carney recently observed, we are a steady partner when predictability is at a premium. Canada's candidacy for the Human Rights Council for 2028 to 2030 bears witness to our values and to the nations represented here. We would be honored to be able to count on your The rule of law is one of the pillars of our society in Canada and it guides our action abroad. Canada's commitment to human rights and international law is strong."},{"t":893,"topic":"Israel-Palestine","text":"This includes our support for those institutions that defend these such as the International Criminal Court. remains unequivocally committed to the charter of the United Nations which Canada helped to shape. Article one sub two of the UN charter underlines a foundational principle of this institution, the self-determination of peoples. And let us be clear, self-determination is a right to which both Israelis and Palestinians are Canada firmly believes that lasting peace and security can be achieved only through a negotiated two-state solution. That means a Palestinian state living alongside Israel in peace, and dignity. Israel's right to exist is not up for And the right of the Palestinian people to self-determination in a state of their own is also not up for debate."},{"t":969,"topic":"Israel-Palestine","text":"The two-state solution remains the guiding principle of our Middle East policy and our actions are calibrated to support this outcome. Alongside our partners, we will continue to target those who lead, arm, and finance Hamas and other terrorist organizations who threaten the security of Israel and the broader region. Hamas must play no role in the governance of Israel's settlements in the West Bank are illegal under international law and an obstacle to peace. That is why Canada announced earlier this month that we intend to restrict trade in goods with illegal Israeli settlements. We will also continue to provide vital humanitarian assistance to civilians in in order to respond to the urgent humanitarian crisis in Sudan."},{"t":1039,"topic":"UN reform","text":"We recently announced financing to the tune of $120 million to help the affected people from Lebanon to Haiti to Gaza and We are supporting efforts to reduce poverty, to strengthen resilience, to promote gender equality, to defend the rights of LGBTQ to I persons and create economic The United Nations system plays a essential role in this regard. But the UN is not and must not be a static organization. While the UN is experiencing major changes, we should ensure that it is ready for the future."},{"t":1104,"topic":"UN reform","text":"We would like to thank Mr. Antonio Gutesh for his efforts over the past decade. We are very much looking forward to cooperating with the new secretary general, be that a man or a woman. &gt;&gt; Mr. President, distinguished colleagues, &gt;&gt; looks very different today than it did when I was growing up in rural Nova The tide has turned. We could spend our time wishing that it had not. But to indulge in nostalgia or to give into despair would be to let our people down. That's not an option. Instead, Canada chooses to move with confidence and strength. Though some would build higher walls and retreat from international engagement, we believe that long-term partnerships are the way to prosperity and security."},{"t":1174,"topic":"UN reform","text":"Though some are turning away from the principles of the United Nations, we remain committed to them. And though some would rather ignore the rupture that we see before our very eyes, we are willing to see the world as it is. Rather than yearn for days gone by, let us together take this opportunity to do right by our people and build together. This is the path that Canada will take and we invite you to join us in Thank you. Merci Miglanch. &gt;&gt; I thank the Minister of Foreign Affairs of Canada."}],"compare":[{"topic":"UN & its reform","share":0.1599,"mean":0.205,"rank":113,"others":170},{"topic":"Russia-Ukraine War","share":0.1308,"mean":0.0348,"rank":18,"others":44},{"topic":"Israel–Palestine","share":0.1263,"mean":0.052,"rank":21,"others":76},{"topic":"Iran","share":0.1214,"mean":0.0132,"rank":5,"others":25},{"topic":"Global Economy","share":0.1132,"mean":0.014,"rank":6,"others":31},{"topic":"Canada","share":0.0593,"mean":0.0,"rank":1,"others":0},{"topic":"Artificial Intelligence","share":0.0591,"mean":0.0504,"rank":68,"others":83},{"topic":"International Law & Order","share":0.0544,"mean":0.0604,"rank":81,"others":102}]};
